"use strict";
// Rejection reasons of every kind, built by the package (engine values).
const shared = { inner: { n: 1 } };
const cyc = { a: 1 };
cyc.self = cyc;
const err = new TypeError("t");
err.extra = 7;
const fn = () => 3;
const reasons = {
  obj: () => ({ a: 1, list: [1, 2] }),
  fn: () => fn,
  cyc: () => cyc,
  err: () => err,
  alias: () => ({ x: shared.inner, y: shared.inner }),
  shared: () => shared,
  num: () => 42,
  nul: () => null,
  arr: () => [1, 2, 3],
};
exports.shared = shared;
exports.cyc = cyc;
exports.err = err;
exports.fn = fn;
exports.fail = (kind) => Promise.reject(reasons[kind]());
exports.failAsync = async (kind) => {
  throw reasons[kind]();
};
